import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span

class LabelTests(unittest.TestCase):
    def test_rounds_both_ends_to_nearest_quarter(self):
        labels = round_spans([Span(544, 1032)], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_exact_half_rounds_up(self):
        labels = round_spans([Span(545, 1025)], 10)
        self.assertEqual(labels, ["09:10-17:10 (8h 00m)"])

    def test_hour_step(self):
        labels = round_spans([Span(544, 1032)], 60)
        self.assertEqual(labels, ["09:00-17:00 (8h 00m)"])

    def test_short_span_pads_minutes(self):
        labels = round_spans([Span(540, 545)], 5)
        self.assertEqual(labels, ["09:00-09:05 (0h 05m)"])

    def test_end_can_round_up_to_midnight(self):
        labels = round_spans([Span(1200, 1439)], 15)
        self.assertEqual(labels, ["20:00-24:00 (4h 00m)"])

    def test_keeps_order_and_count(self):
        spans = [Span(600, 780), Span(480, 540)]
        labels = round_spans(spans, 60)
        self.assertEqual(labels[0], "10:00-13:00 (3h 00m)")
        self.assertEqual(labels[1], "08:00-09:00 (1h 00m)")

    def test_empty_list(self):
        self.assertEqual(round_spans([], 15), [])

class CollapseTests(unittest.TestCase):
    def test_span_that_rounds_to_nothing_raises(self):
        with self.assertRaises(ValueError):
            round_spans([Span(541, 547)], 15)

class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 120, 2.5, "15"):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_spans([Span(540, 600)], step)

    def test_bad_step_raises_even_with_no_spans(self):
        with self.assertRaises(ValueError):
            round_spans([], 0)
